draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // two characters
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 - 20);
  ctx.lineTo(W/4, H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 - 10);
  ctx.lineTo(W/4 - 10, H/2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 10);
  ctx.lineTo(W/4 - 10, H/2);
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(3*W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(3*W/4, H/2 - 20);
  ctx.lineTo(3*W/4, H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(3*W/4, H/2 - 10);
  ctx.lineTo(3*W/4 + 10, H/2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(3*W/4, H/2 + 10);
  ctx.lineTo(3*W/4 + 10, H/2);
  ctx.stroke();

  // broken trust line
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(W/4 + 20, H/2);
  ctx.lineTo(3*W/4 - 20, H/2);
  ctx.setLineDash([10 + 5 * Math.sin(t), 10 - 5 * Math.sin(t)]);
  ctx.stroke();
  ctx.setLineDash([]);

  ctx.restore();
}
